	private static void assertFusionVisitsLeavesOnce(UnaryOperator<IrBGP> transform) {
		AtomicInteger visits = new AtomicInteger();
		IrBGP nested = new IrBGP(false);
		nested.add(new CountingLeaf(visits, false));
		for (int depth = 0; depth < 8; depth++) {
			IrUnion union = new IrUnion(true);
			union.addBranch(nested);
			IrBGP other = new IrBGP(true);
			other.add(new IrFilter("?x > " + depth, false));
			union.addBranch(other);
			nested = new IrBGP(true);
			nested.add(union);
		}
		transform.apply(nested);
		assertEquals(1, visits.get(), "One fusion pass must visit each original leaf once");
	}

	@Test
	void valuesGroupingReachesNestedUnionBranchesOnce() {
		IrValues values = new IrValues(false);
		values.getVarNames().add("s");
		values.getRows().add(List.of("<urn:s>"));
		IrBGP leafBranch = new IrBGP(true);
		leafBranch.add(values);
		leafBranch.add(new IrPathTriple(Var.of("s"), "!(<urn:p>)", Var.of("o"), false, Set.of()));
		IrUnion inner = new IrUnion(true);
		inner.addBranch(leafBranch);
		IrBGP outerBranch = new IrBGP(true);
		outerBranch.add(inner);
		IrUnion outer = new IrUnion(true);
		outer.addBranch(outerBranch);
		IrBGP where = new IrBGP(false);
		where.add(outer);
		IrBGP transformed = GroupValuesAndNpsInUnionBranchTransform.apply(where);
		IrUnion transformedOuter = (IrUnion) transformed.getLines().get(0);
		IrUnion transformedInner = (IrUnion) transformedOuter.getBranches().get(0).getLines().get(0);
		IrBGP groupedBranch = transformedInner.getBranches().get(0);
		assertEquals(1, groupedBranch.getLines().size());
		assertTrue(groupedBranch.getLines().get(0) instanceof IrBGP);
		assertEquals(2, leafBranch.getLines().size(), "Original branch must remain unchanged");
		String once = new TupleExprIRRenderer().render(selectWithWhere(transformed), null, true);
		String twice = new TupleExprIRRenderer().render(
				selectWithWhere(GroupValuesAndNpsInUnionBranchTransform.apply(transformed)), null, true);
		assertEquals(once, twice);
	}

