	@Test
	void groupInputModifiersStayNestedWithoutParserScopeFlags() {
		for (String duplicateModifier : List.of("DISTINCT", "REDUCED", "")) {
			String query = "SELECT ?selected (COUNT(*) AS ?links) WHERE { { SELECT " + duplicateModifier
					+ " ?selected WHERE { VALUES ?selected { 1 1 2 } } ORDER BY ?selected LIMIT 2 OFFSET 1 } } "
					+ "GROUP BY ?selected";
			var algebra = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
			algebra.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Slice slice) {
					slice.setVariableScopeChange(false);
					super.meet(slice);
				}

				@Override
				public void meet(Distinct distinct) {
					distinct.setVariableScopeChange(false);
					super.meet(distinct);
				}

				@Override
				public void meet(Reduced reduced) {
					reduced.setVariableScopeChange(false);
					super.meet(reduced);
				}

				@Override
				public void meet(Order order) {
					order.setVariableScopeChange(false);
					super.meet(order);
				}
			});
			IrSelect outer = new TupleExprIRRenderer().toIRSelectRaw(algebra);
			assertEquals(-1, outer.getLimit());
			assertEquals(-1, outer.getOffset());
			assertEquals(false, outer.isDistinct());
			assertEquals(false, outer.isReduced());
			assertTrue(outer.getOrderBy().isEmpty());
			assertEquals(1, outer.getGroupBy().size());
			IrSelect inner = ((IrSubSelect) outer.getWhere().getLines().get(0)).getSelect();
			assertEquals(2, inner.getLimit());
			assertEquals(1, inner.getOffset());
			assertEquals("DISTINCT".equals(duplicateModifier), inner.isDistinct());
			assertEquals("REDUCED".equals(duplicateModifier), inner.isReduced());
			assertEquals(1, inner.getOrderBy().size());
			assertTrue(inner.getGroupBy().isEmpty());
			assertRoundTrip(query);
		}
	}

